    "en": (COLUMNS, "%Y-%m-%d"),
    'de': (['id', 'art', 'sorte', 'menge', 'ernte', 'keim_%', 'regal'], '%d.%m.%y'),
    'fr': (['id', 'espèce', 'variété', 'qté', 'récolte', 'germ_%', 'étagère'], '%d.%m.%Y'),
}


