class ImportReport:
    def __init__(self):
        self.added = 0
        self.skipped = []

LOW_STOCK = 5

class Catalog:
    def __init__(self):
        self._packets = {}
        self._audit = []
        self._handlers = {"added": [], "removed": [], "low_stock": []}
        self._holds = {}

    def add(self, packet):
        if packet.id in self._packets:
            raise ValueError(f"duplicate packet id: {packet.id}")
        if packet.qty <= 0:
            raise ValueError("quantity must be positive")
        self._packets[packet.id] = packet
        self._record("add", packet.id, packet.qty)
        self._emit("added", packet)

    def get(self, pid):
        try:
            return self._packets[pid]
        except KeyError:
            raise KeyError(f"no such packet: {pid}") from None

    def remove(self, pid):
        packet = self.get(pid)
        del self._packets[pid]
        self._record("remove", pid, -packet.qty)
        self._emit("removed", packet)
        self._holds.pop(pid, None)
        return packet

    def take(self, pid, n, who=None):
