        mine = self._holds.get(pid, {}).get(who, 0) if who is not None else 0
        if n <= 0 or n > self.available(pid) + mine:
            raise ValueError(f"cannot take {n} from {pid} (have {packet.qty}, {self.available(pid)} available)")
