            del self._packets[pid]
        self._record("take", pid, -n)
        if left == 0:
            self._emit("removed", packet)
        elif left <= LOW_STOCK:
            self._emit("low_stock", packet)
        if mine:
            holds = self._holds[pid]
            holds[who] -= min(n, mine)
            if holds[who] == 0:
                del holds[who]
            if not holds:
                del self._holds[pid]
        return left

    def packets(self):
        return [self._packets[k] for k in sorted(self._packets)]

    def query(self, **opts):
        rows = self.packets()
        if "species" in opts:
            want = opts.pop("species").lower()
            rows = [p for p in rows if p.species.lower() == want]
        if "min_germ" in opts:
