    def from_dict(cls, d):
        cat = cls()
        for item in d.get("packets", []):
            cat._packets[item["id"]] = Packet.from_dict(item)
        cat._audit = [dict(e) for e in d.get("audit", [])]
        cat._holds = {pid: dict(h) for pid, h in d.get("holds", {}).items()}
        return cat

